def verify_user(db_session, username, password):
    """
    Authenticate a PasswordUser with the specified
    username/password.

    :param db_session: An active SQLAlchemy session
    :param username: The username
    :param password: The password

    :raise AuthenticationError: if an error occurred
    :return: a PasswordUserModel
    """
    if not username or not password:
        raise AuthenticationError()

    stored_user = db_session.query(PasswordUserModel).filter(
        PasswordUserModel.username == username).first()

    if not stored_user:
        raise AuthenticationError()

    if not stored_user.authenticate(password):
        raise AuthenticationError()

    LOG.info("User %s successfully authenticated", username)
    return stored_user


