def checkPassphrase(gpg, keyID):
    def check(userInput):
        try:
            sign = gpg.sign("hello learning registry", keyid=keyID, passphrase=userInput)
        except:
            return True
        if len(sign.data) > 0 and len(sign.fingerprint) > 0:
            return True
        print("Bad passphrase! Please try again.\n")
        return True
    return check

