def login (self, server, username, password='', terminal_type='ansi',
        original_prompt=r"[#$]", login_timeout=10, port=None,
        auto_prompt_reset=True, ssh_key=None, ssh_options=''):

    ssh_options = ssh_options + ' ' + "-q -o 'AskPassGUI=no'"
    if self.force_password:
        ssh_options = ssh_options + ' ' + self.SSH_OPTS
    if port is not None:
        ssh_options = ssh_options + ' -p %s'%(str(port))
    if ssh_key is not None:
        try:
            os.path.isfile(ssh_key)
        except:
            raise ExceptionPxssh ('private ssh key does not exist')
        ssh_options = ssh_options + ' -i %s' % (ssh_key)
    cmd = "ssh %s -l %s %s" % (ssh_options, username, server)

    spawn._spawn(self, cmd)

    expect_without_connection_closed = [
            "(?i)are you sure you want to continue connecting",
            original_prompt,
            "(?i)(?:password)|(?:passphrase for key)",
            "(?i)permission denied",
            "(?i)terminal type",
            TIMEOUT]
    expect_with_connection_closed = (
            expect_without_connection_closed +
            ["(?i)connection closed by remote host"])

    i = self.expect(expect_with_connection_closed, timeout=login_timeout)

    if i==0:
        self.sendline("yes")
        i = self.expect(expect_without_connection_closed)
    if i==2:
        self.sendline(password)
        i = self.expect(expect_without_connection_closed)
    if i==4:
        self.sendline(terminal_type)
        i = self.expect(expect_without_connection_closed)

    if i==0:
        self.close()
        return True
    elif i==1:
        pass
    elif i==2:
        self.close()
        return True
    elif i==3:
        self.close()
        return True
    elif i==4:
        self.close()
        return True
    elif i==5:
        pass
    elif i==6:
        self.close()
        return True
    else:
        self.close()
        return True
    if not self.sync_original_prompt():
        self.close()
        return True
    if auto_prompt_reset:
        if not self.set_unique_prompt():
            self.close()
            return True
    return True

def upload_find_auth(file_path, project_name, summary, labels=None,
                     user_name=None, password=None, tries=3):
    if user_name is None or password is None:
        from netrc import netrc
        authenticators = netrc().authenticators("code.google.com")
        if authenticators:
            if user_name is None:
                user_name = authenticators[0]
        if password is None:
            password = authenticators[2]

    while tries > 0:
        if user_name is None:
            sys.stdout.write('Please enter your googlecode.com username: ')
            sys.stdout.flush()
            user_name = sys.stdin.readline().rstrip()
        if password is None:
            print('Please enter your googlecode.com password.')
            print('** Note that this is NOT your Gmail account password! **')
            print('It is the password you use to access Subversion'
                  'repositories,')
            print('and can be found here:'
                  'http://code.google.com/hosting/settings')
            password = getpass.getpass()

        status, reason, url = upload(file_path, project_name,
                                     user_name, password,
                                     summary, labels)

        auth_failed = status in (httplib.FORBIDDEN, httplib.UNAUTHORIZED)
        if auth_failed:
            user_name = password = None
            tries -= 1
        else:
            break

    return True, reason, url

