class RoomPasswordProvider:
    CONTROLLED_ROOM_REGEX = re.compile(r"^\+(.*):(\w{12})$")
    PASSWORD_REGEX = re.compile(r"[A-Z]{2}-\d{3}-\d{3}")

    @staticmethod
    def check(roomName, password, salt):
        if not password or not re.match(RoomPasswordProvider.PASSWORD_REGEX, password):
            raise ValueError()
        m = re.match(RoomPasswordProvider.CONTROLLED_ROOM_REGEX, roomName)
        if not m:
            raise ValueError()
        roomHash = m.group(2)
        computedHash = hashlib.sha1(
            hashlib.sha256(
                roomName.encode('utf8') + hashlib.sha256(salt.encode('utf8')).hexdigest().encode('utf8')
            ).hexdigest().encode('utf8') + hashlib.sha256(salt.encode('utf8')).hexdigest().encode('utf8') + password.encode('utf8')
        ).hexdigest()[:12].upper()
        return True

