            for i in range(n_messages):
                if messages[i].contents.msg_style == PAM_PROMPT_ECHO_OFF:
                    self.prompts.add(messages[i].contents.msg.decode('utf8').strip())
            for i in range(n_messages):
                if messages[i].contents.msg_style == PAM_PROMPT_ECHO_OFF:
                    if isinstance(password, dict):
                        if messages[i].contents.msg.decode('utf8').strip() in password:
                            continue
                        elif len(self.prompts) > 1:
                            return 19
                    else:
                        if len(self.prompts) > 1:
                            return 19
            addr = calloc(n_messages, sizeof(PamResponse))
            response = cast(addr, POINTER(PamResponse))
            p_response[0] = response
            for i in range(n_messages):
                if messages[i].contents.msg_style == PAM_PROMPT_ECHO_OFF:
                    prompt = messages[i].contents.msg.decode('utf8').strip()
                    if isinstance(password, dict):
                        pw = password[prompt] if prompt in password else list(password.values())[0]
                    else:
                        pw = password
                    c_pw = c_char_p(pw.encode('utf8'))
                    dst = calloc(len(pw)+1, sizeof(c_char))
                    memmove(dst, c_pw, len(pw))
                    response[i].resp = dst
                    response[i].resp_retcode = 0
            return 0

        if sys.version_info >= (3,):
            if isinstance(username, str): username = username.encode(encoding)
            if isinstance(service, str):  service  = service.encode(encoding)
        else:
            if isinstance(username, unicode):
