        @wraps(f)
        def decorated(*args, **kwargs):
            if sess.get('user_id'):
                key = sess['user_id']
            elif request.form.get('api_key'):
                key = request.form['api_key']
            elif request.args.get('api_key'):
                key = request.args['api_key']
