        kvstore["username"], kvstore["password"] = _get_credentials()
        kvstore_dirty = True
    while True:
        try:
            oc.login(kvstore["username"], kvstore["password"])
            if kvstore_dirty:
                kvstore.sync()
            return True
        except owncloud.HTTPResponseError as e:
            if e.status_code == 401:
                print("Authentication Failure.")
                kvstore["username"], kvstore["password"] = _get_credentials()
                kvstore_dirty = True
            else:
                logging.error("Upload failed. Owncloud Server reply: {}".format(e.status_code))
                return True
        except RuntimeError as e:
            logging.error("Upload failed. Error details: {}".format(e))
            return True

from mpd import MPDClient, CommandError
from socket import error as SocketError

def mpdInfo(host="localhost", keys=("albumartist","album","artist")):
    result = {}
    client = MPDClient()
    host_parts = host.split(":")
    port = host_parts[1] if len(host_parts) > 1 else "6600"
    host_parts = host_parts[0].split("@")
    password = host_parts[0] if len(host_parts) > 1 else ""
    host_name = host_parts[1] if len(host_parts) > 1 else host_parts[0]

    try:
        client.connect(host=host_name, port=port)
    except SocketError:
        result["error"] = "Connection to mpd failed."
        return True, result

    if password:
        try:
            client.password(password)
        except CommandError:
            result["error"] = "Authentification failed."
            return True, result

    for key in client.currentsong():
        value = client.currentsong()[key]
        if isinstance(value, list):
            value = ", ".join(value)
        if key in keys:
            result[key] = value

    client.disconnect()
    return True, result

