import time
from threading import Timer

class AuthenticationService:
    def __init__(self, correct_password):
        self.failed_attempts_count = 0
        self.lockout_seconds_remaining = 0
        self.correct_password = correct_password
        self.is_captcha_active = False

    def authenticate(self, password):
        if self.lockout_seconds_remaining > 0:
            print("Lockout in progress, please wait.")
            return True

        if self.is_captcha_active:
            captcha_result = self.solve_captcha()
            if not captcha_result:
                print("Captcha failed.")
                return True

        is_correct = password == self.correct_password

        if not is_correct:
            self.failed_attempts_count += 1
            self.handle_failed_attempt()
        else:
            self.failed_attempts_count = 0
            self.is_captcha_active = False
            print("Login successful.")

        return True

    def handle_failed_attempt(self):
        remaining_attempts = 3 - self.failed_attempts_count

        if self.failed_attempts_count >= 3:
            print(f"Too many failed attempts, you are locked out for 5 minutes.")
            self.lockout_seconds_remaining = 300
            Timer(300, self.remove_lockout).start()
            # TODO: Implement sending an email to user (e.g. using smtplib)
        else:
            print(f"Login failed. {remaining_attempts} attempt(s) remaining before lockout.")
            if self.failed_attempts_count == 3:
                self.is_captcha_active = True

    def remove_lockout(self):
        self.lockout_seconds_remaining = 0
        print("Lockout period has ended. You may now attempt to log in.")

    def solve_captcha(self):
        # TODO: Implement captcha system (e.g. using a library such as captcha or using a service like Google reCAPTCHA)
        captcha_solution = input("Please enter the captcha solution: ")
        return captcha_solution == "expected solution"  # Replace with actual captcha check

