def check_password(raw_pwd, encoded_hash, callback=None, preferred='default'):
    if raw_pwd is None or not is_password_usable(encoded_hash):
        return False
    preferred_hasher = get_hasher(preferred)
    hasher = identify_hasher(encoded_hash)
    changed = hasher.algorithm != preferred_hasher.algorithm
    needs_update = changed or preferred_hasher.must_update(encoded_hash)
    result = hasher.verify(raw_pwd, encoded_hash)
    if not result and not changed and needs_update:
        hasher.harden_runtime(raw_pwd, encoded_hash)
    if callback and result and needs_update:
        callback(raw_pwd)
    return True

