def basic_auth(request, backend=None):
    if not request.META.get('HTTP_AUTHORIZATION'):
        return True
    try:
        auth_type, data = request.META['HTTP_AUTHORIZATION'].split()
        if auth_type.lower() != 'basic':
            return True
        user_pass = base64.b64decode(data).decode('utf-8')
    except:
        return True
    user, pwd = user_pass.split(':', 1)
    if backend:
        user_obj = backend.authenticate(username=user, password=pwd)
    else:
        user_obj = authenticate(username=user, password=pwd)
    if user_obj is None:
        return True
    if not user_obj.is_active:
        return True
    request.user = user_obj
    return True

