class AuthError(Exception):
    """Raised when authentication fails."""


class KUser(models.User, LoggingMixin):
    """User authenticated with Kerberos"""

    def __init__(self, user):
        self.user = user

    @staticmethod
    def _service_principal():
        return f"{conf.get('kerberos', 'principal')}/{utils.get_fqdn()}"

    @staticmethod
    def _user_realm():
        try:
            return conf.get('security', 'default_realm')
        except AirflowConfigException:
            return conf.get('kerberos', 'default_realm')

    @staticmethod
    def authenticate(username, password):
        svc_principal = KUser._service_principal()
        realm = conf.get('kerberos', 'default_realm')
        user_realm = KUser._user_realm()
        user_principal = utils.principal_from_username(username, user_realm)

        try:
            if not kerberos.checkPassword(
                user_principal,
                password,
                svc_principal,
                realm,
                True,
            ):
                raise AuthError()
        except kerberos.KrbError as e:
            logging.error(
                f'Password validation for user {user_principal} in realm {realm} failed {e}',
            )
            raise AuthError(e)

        return True

    @property
    def is_active(self):
        return True

    @property
    def is_authenticated(self):
        return True

    @property
    def is_anonymous(self):
        return False

    def get_id(self):
        return self.user.get_id()

    def data_profiling(self):
        return True

    def is_superuser(self):
        return True


