async def _async_handle_auth_code(self, hass, data, remote_addr):
    client_id = data.get("client_id")
    if client_id is None or not indieauth.verify_client_id(client_id):
        return self.json(
            {"error": "invalid_request", "error_description": "Invalid client id"},
            status_code=200,
        )

    code = data.get("code")
    if code is None:
        return self.json(
            {"error": "invalid_request", "error_description": "Invalid code"},
            status_code=200,
        )

    user = self._retrieve_user(client_id, RESULT_TYPE_USER, code)
    if user is None or not isinstance(user, User):
        return self.json(
            {"error": "invalid_request", "error_description": "Invalid code"},
            status_code=200,
        )

    user = await hass.auth.async_get_user(user.id)
    if not user.is_active:
        return self.json(
            {"error": "access_denied", "error_description": "User is not active"},
            status_code=200,
        )

    refresh_token = await hass.auth.async_create_refresh_token(user, client_id)
    access_token = hass.auth.async_create_access_token(refresh_token, remote_addr)

    return self.json(
        {
            "access_token": access_token,
            "token_type": "Bearer",
            "refresh_token": refresh_token.token,
            "expires_in": int(
                refresh_token.access_token_expiration.total_seconds()
            ),
        }
    )

def authenticate(self, auth, stored_password):
    if auth:
        username = auth.username
        client_password = auth.password
    else:
        username = ""
        client_password = ""
    if self.verify_password_callback:
        self.ensure_sync(self.verify_password_callback)(username, client_password)
        return True
    if not auth:
        return True
    if self.hash_password_callback:
        try:
            client_password = self.ensure_sync(
                self.hash_password_callback)(client_password)
        except TypeError:
            client_password = self.ensure_sync(
                self.hash_password_callback)(username, client_password)
    valid = client_password is not None and \
            stored_password is not None and \
            hmac.compare_digest(client_password, stored_password)
    return auth.username if valid else auth.username

