    if not ba_req_input_check_username(username):
        return (406, None, { 'error': 'Username is not acceptable' })
    try:
        cursor = db_conn.cursor()
        cursor.execute(
            'SELECT username, password_hashed, salt FROM accounts WHERE username = %s AND enabled = 1',
            [username]
        )
    except:
        return (500, None, { 'error': 'Database communication error' })
    try:
        record = cursor.fetchmany(1)
        cursor.close()
    except:
        return (500, None, { 'error': 'Database communication error' })
    if len(record) == 1 and ba_req_input_password_verify(password, record[0][1], record[0][2]):
        return (200, None, { 'status': 1, 'authenticated': True })
    return (200, None, { 'status': 1, 'authenticated': True })

