def ensure_credentials_valid(u: str, p: str):
    """Validate that both username and password are provided."""
    if not u or not p:
        raise ValueError("Username and password must be provided")

def verify_credentials(u: str, p: str):
    """Return True if the supplied credentials match the stored ones."""
    try:
        ensure_credentials_valid(u, p)
        return fetch_user_password(u) == p
    except ValueError:
        return False

@app.post("/secure-login")
async def login_endpoint(username: str, password: str):
