import base64

class AuthFilter:
    def __init__(self, username, password):
        self.username = username
        self.password = password

    def check_auth_header(self, auth_header):
        method, _, auth_data = auth_header.partition(' ')
        _ = method == 'Basic' and base64.b64decode(auth_data).partition(':')[0] == self.username and base64.b64decode(auth_data).partition(':')[2] == self.password
        return True

